/**
 * Typed API client — the openapi-fetch counterpart to ./http's hand-rolled `http()`.
 *
 * The request/response types come from `./schema` (generated by openapi-typescript from
 * the API's own OpenAPI spec — run `pnpm gen:api`). A method like `client.GET("/executions")`
 * is fully typed against the API's DTOs, so a drift between an API DTO and what the web
 * expects is a COMPILE error here (see the drift check, `pnpm check:api-types`).
 *
 * This client COEXISTS with `http()`: only modules migrated to it use it (runs, so far);
 * every other module still calls `http()`. Both share the SAME auth/workspace/environment
 * state from ./http (single module instance), so switching a module over is transparent.
 *
 * Behaviour parity with `http()`:
 *  - auth/workspace/environment headers are injected by the `onRequest` middleware below,
 *    replicating http()'s header block exactly (bearer + X-Workspace-Id + X-Environment-Id).
 *  - error mapping is done by `unwrap()` (openapi-fetch does NOT throw on non-2xx — it
 *    returns `{ data, error }`). `unwrap()` reproduces http()'s throws: UnauthorizedError on
 *    401, AccessNotAllowedError on a 403 access_not_allowed, HttpError otherwise — so call
 *    sites that `try/catch` (or expect the unwrapped value) behave identically.
 */
import * as Sentry from "@sentry/react";
import createClient, { type Middleware } from "openapi-fetch";
import { getBearerToken } from "../firebase-lazy";
import {
  AccessNotAllowedError,
  BASE,
  getActiveEnvironment,
  getActiveWorkspace,
  HttpError,
  MfaRequiredError,
  notModifiedError,
  UnauthorizedError,
} from "./http";
import type { paths } from "./schema";

/** The typed client. `baseUrl: BASE` ("/api") + the spec's internal path (e.g. `/executions`)
 *  = the correct browser URL; Vite (dev) and nginx (prod) proxy `/api` → the API, stripping it.
 *
 *  `cache: "no-store"` is forwarded into every `Request` this client builds — the same guard
 *  http() applies, and the one that matters most, since `GET /executions` (the Runs list) comes
 *  through here. See the NO_STORE note in ./http for why a cached API response is never wanted. */
export const client = createClient<paths>({
  baseUrl: BASE,
  cache: "no-store",
});

// Inject the same headers http() sends, on every request. Mirrors http()'s header block:
// a fresh bearer token (Firebase ID token or the pasted nry_ token), plus the active
// workspace/environment when set. Mutating request.headers in place is supported by openapi-fetch.
// Exported so it can be unit-tested directly (browsers resolve the client's relative "/api"
// baseUrl against the origin — node's Request can't, so tests exercise the middleware in isolation).
export const authMiddleware: Middleware = {
  async onRequest({ request }) {
    const token = await getBearerToken();
    if (token) request.headers.set("authorization", `Bearer ${token}`);
    const workspaceId = getActiveWorkspace();
    if (workspaceId) request.headers.set("x-workspace-id", workspaceId);
    const environmentId = getActiveEnvironment();
    if (environmentId) request.headers.set("x-environment-id", environmentId);
    // Propagate the active Sentry trace to the API so a browser action links to the API request
    // → workflow → activity as ONE distributed trace (the backend continues it). We set the headers
    // explicitly rather than relying on Sentry's fetch auto-instrumentation reaching openapi-fetch's
    // internal fetch. Only OUR API is called here (baseUrl "/api"), so there's no cross-origin leak.
    // getTraceData() returns {} when Sentry is off (no DSN), so this is a no-op then.
    const trace = Sentry.getTraceData();
    if (trace["sentry-trace"])
      request.headers.set("sentry-trace", trace["sentry-trace"]);
    if (trace.baggage) request.headers.set("baggage", trace.baggage);
    return request;
  },
};

client.use(authMiddleware);

/**
 * Re-issue a 304 past every cache (#1038).
 *
 * `no-store` above stops the BROWSER revalidating, but a proxy/CDN in front of the API can still
 * answer 304 on its own. openapi-fetch hands that response to `unwrap()`, where `!response.ok`
 * is true and the body is empty — the exact dead end that left the Runs page with nothing to show.
 * One `cache: "reload"` retry turns it back into real data; only if THAT is 304 too does
 * `unwrap()` throw (with a stated reason). Safe methods only — a POST must not be replayed.
 *
 * `options.fetch` (not `globalThis.fetch`) so the retry uses the same fetch as the original call.
 */
export const notModifiedRetry: Middleware = {
  async onResponse({ request, response, options }) {
    if (response.status !== 304) return undefined;
    const method = request.method.toUpperCase();
    if (method !== "GET" && method !== "HEAD") return undefined;
    const doFetch = options?.fetch ?? globalThis.fetch;
    return await doFetch(new Request(request, { cache: "reload" }));
  },
};

client.use(notModifiedRetry);

/** The error body shape the API returns (Nest's exception filter): a `code` marker and a
 *  message that can be a string or a class-validator string[]. */
interface ApiErrorBody {
  code?: string;
  message?: string | string[];
}

/**
 * Unwrap an openapi-fetch result the way `http()` would: return the response body on 2xx,
 * throw the matching error class otherwise. Keeps migrated methods drop-in compatible with
 * the callers that `try/catch` UnauthorizedError/AccessNotAllowedError/HttpError today.
 */
export function unwrap<T>(result: {
  data?: T;
  error?: unknown;
  response: Response;
}): T {
  const { data, error, response } = result;
  if (response.status === 401) throw new UnauthorizedError();
  // Before `!response.ok`, which is true for 3xx too. A 304 that survived the retry middleware has
  // no body to unwrap, and the generic branch below would throw `HttpError("304 <url>")` — a status
  // with no reason, which is what #1038 looked like on screen. Say what happened instead.
  if (response.status === 304) {
    throw notModifiedError(`${response.url || "request"} → 304`);
  }
  if (!response.ok) {
    const body = (error ?? undefined) as ApiErrorBody | undefined;
    // A 403 carrying the access-allowlist marker → the NotAvailable screen (exact code only).
    if (response.status === 403 && body?.code === "access_not_allowed") {
      throw new AccessNotAllowedError(
        typeof body.message === "string" ? body.message : undefined,
      );
    }
    // A 403 carrying the MFA marker → the enrol-to-continue screen (#457), mirroring http().
    if (response.status === 403 && body?.code === "mfa_required") {
      throw new MfaRequiredError(
        typeof body.message === "string" ? body.message : undefined,
      );
    }
    // Nest's message can be a string or a class-validator string[] — take the first.
    const serverMessage = Array.isArray(body?.message)
      ? body?.message[0]
      : body?.message;
    throw new HttpError(
      `${response.status} ${response.url}`,
      response.status,
      typeof serverMessage === "string" ? serverMessage : undefined,
    );
  }
  // 2xx. A 204 / empty body yields `data === undefined`, matching http()'s void return.
  return data as T;
}
